import numpy as np

G = 9.81
MASS = 0.600

SQUEEZE_ONLY = [
    (np.array([0.025, 0.000, 0.000]), np.array([-30.000, 0.000, 0.000])),
    (np.array([-0.025, 0.000, 0.000]), np.array([30.000, 0.000, 0.000])),
]
