    (np.array([0.025, 0.000, 0.000]), np.array([-30.000, 0.000, 2.943])),
    (np.array([-0.025, 0.000, 0.000]), np.array([30.000, 0.000, 2.943])),
]


def wrench(r, f):
    return np.concatenate([f, np.cross(r, f)])


def net_wrench(contacts, mass):
    net = np.zeros(6)
    for r, f in contacts:
        net = net + wrench(r, f)
    net[2] = net[2] - mass * G
    return net


for name, grip in [("squeeze only ", SQUEEZE_ONLY), ("with friction", WITH_FRICTION)]:
    r = net_wrench(grip, MASS)
    print(name, np.round(r, 3), "residual", round(float(np.linalg.norm(r)), 3))

