              np.array([0.025, -0.010]), np.array([0.0, 1.0]))


def angle_between(a, b):
    return math.degrees(math.acos(float(np.clip(np.dot(a, b), -1.0, 1.0))))


def antipodal_error(p1, n1, p2, n2):
    u = (p2 - p1) / np.linalg.norm(p2 - p1)
    return max(angle_between(n1, u), angle_between(n2, -u))


for name, pair in [("flat faces ", FLAT_PAIR), ("two chamfers", CHAMFER_PAIR), ("mixed      ", MIXED_PAIR)]:
    print(name, "error deg", round(antipodal_error(*pair), 2))

