import numpy as np

LIFT = 0.120
STANDOFF = 0.050
TOP_DOWN = (np.array([0.400, 0.000, 0.060]), np.array([0.0, 0.0, -1.0]))
SIDE_ON = (np.array([0.400, 0.000, 0.060]), np.array([1.0, 0.0, 0.0]))


def pregrasp(grasp, approach, standoff):
    return grasp - standoff * approach


def retreat(grasp):
    return grasp + LIFT * np.array([0.0, 0.0, 1.0])


for name, (grasp, approach) in [("top down", TOP_DOWN), ("side on ", SIDE_ON)]:
    pre = pregrasp(grasp, approach, STANDOFF)
    print(name, "pre", np.round(pre, 3), "grasp", np.round(grasp, 3), "retreat", np.round(retreat(grasp), 3))
    print("         travel to grasp mm", round(float(np.linalg.norm(grasp - pre)) * 1000.0, 1))

import math
import numpy as np

JAW_HALF_WIDTH = 0.009
HALF_OPENING = 0.032
TARGET = np.array([0.000, 0.000])
NEIGHBOURS = [(np.array([0.038, 0.000]), 0.014), (np.array([0.000, -0.040]), 0.012)]
YAWS = (0, 45, 90, 135)


def finger_centres(yaw):
    a = math.radians(yaw)
    axis = np.array([math.cos(a), math.sin(a)])
    return [TARGET + HALF_OPENING * axis, TARGET - HALF_OPENING * axis]


def finger_hits(centre, neighbours):
    for c, radius in neighbours:
        if float(np.linalg.norm(centre - c)) < radius + JAW_HALF_WIDTH:
            return True
    return False


def rotation_ok(yaw, neighbours):
    return bool(not any(finger_hits(c, neighbours) for c in finger_centres(yaw)))


for yaw in YAWS:
    fingers = finger_centres(yaw)
    hits = [finger_hits(c, NEIGHBOURS) for c in fingers]
    print("yaw", str(yaw).rjust(3), "finger centres", np.round(np.array(fingers), 3).tolist(),
          "hits", hits, "usable", rotation_ok(yaw, NEIGHBOURS))

