SIGMAS = (0.0040, 0.0015)


def feasible(offset):
    return abs(offset) <= 0.5 * PART_LENGTH - PAD_HALF


def robustness(nominal_offset, sigma):
    rng = np.random.default_rng(77)
    successes = 0
    POSE_SIGMA = sigma
    for _ in range(TRIALS):
        dx = float(rng.normal(0.0, POSE_SIGMA))
        if feasible(nominal_offset + dx):
            successes = successes + 1
    return successes / float(TRIALS)


print("largest usable offset mm", round((0.5 * PART_LENGTH - PAD_HALF) * 1000.0, 1), "trials", TRIALS)
for sigma in SIGMAS:
    for name, nominal in CANDIDATES:
        print("vision sigma mm", str(round(sigma * 1000.0, 1)).rjust(4), name,
              "nominal offset mm", str(round(nominal * 1000.0, 1)).rjust(5),
              "success rate", round(robustness(nominal, sigma), 4))

