    ("cast block   ", 0.040, 2.100, 0.60, 300.0, 0.004, 0.070, 1.0),
]
MARGIN_FACTOR = 1.20


def hardware_check(width, mass, wall_gap):
    if not width + 2.0 * (PAD_THICKNESS + APPROACH_GAP) <= MAX_OPENING:
        return "wider than the stroke, needs bigger jaws"
    if width < MIN_GRIP_WIDTH:
        return "thinner than the jaws close"
    if mass > GRIPPER_PAYLOAD:
        return "over the gripper payload"
    if wall_gap < PAD_THICKNESS + APPROACH_GAP:
        return "needs a push off the wall first"
    return None


def force_check(mass, mu, crush):
    lo = SAFETY * mass * G / (2.0 * mu)
    if lo > crush:
        return "no force window, needs softer pads", 0.0
    return None, min(lo * MARGIN_FACTOR, crush)


def stages(width, mass, mu, crush, wall_gap):
    reason = hardware_check(width, mass, wall_gap)
    if reason is not None:
        return reason, 0.0
    return force_check(mass, mu, crush)


